import{_ as o,r as s,o as i,c as l,e as t,a as p,s as c}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Localization & Multisite - October CMS - 4.x","titleTemplate":false,"description":"Understand the different approaches to localization and multisite in October CMS.","frontmatter":{"subtitle":"Understand the different approaches to localization and multisite in October CMS."},"headers":[{"level":2,"title":"Choosing an Approach","slug":"choosing-an-approach","link":"#choosing-an-approach","children":[]},{"level":2,"title":"Locale Strings","slug":"locale-strings","link":"#locale-strings","children":[]},{"level":2,"title":"Multisite","slug":"multisite","link":"#multisite","children":[]},{"level":2,"title":"Translatable","slug":"translatable","link":"#translatable","children":[]},{"level":2,"title":"MultisiteGroup","slug":"multisitegroup","link":"#multisitegroup","children":[]},{"level":2,"title":"Combining Approaches","slug":"combining-approaches","link":"#combining-approaches","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/extend/multisite/introduction.md","filePath":"4.x/extend/multisite/introduction.md"}'),r={name:"4.x/extend/multisite/introduction.md"};function u(d,a,h,g,k,m){const n=s("pre-heading"),e=s("post-heading");return i(),l("div",null,[t(n),a[0]||(a[0]=p("h1",null,"Localization & Multisite",-1)),t(e),a[1]||(a[1]=c(`<p>October CMS provides several approaches for handling multiple languages and multiple websites. Choosing the right approach depends on what you need to translate and how your sites are structured.</p><h2 id="choosing-an-approach"><a href="#choosing-an-approach" class="header-anchor">#</a> Choosing an Approach</h2><p>The following table summarizes the five approaches available. Most projects will use one or two of these.</p><div class="table"><table tabindex="0"><thead><tr><th>Approach</th><th>What it does</th><th>Level</th></tr></thead><tbody><tr><td><strong>Locale Strings</strong></td><td>Translates UI strings via <code>lang/en.json</code> files</td><td>UI strings</td></tr><tr><td><strong>Multisite</strong></td><td>Duplicates the whole record per site</td><td>Record-level</td></tr><tr><td><strong>Translatable</strong></td><td>Translates individual model attributes</td><td>Attribute-level</td></tr><tr><td><strong>MultisiteGroup</strong></td><td>Scopes records to a site group (tenant)</td><td>Multi-tenancy</td></tr><tr><td><strong>MultisiteGroup + Translatable</strong></td><td>Multi-tenancy with translated attributes</td><td>Combined</td></tr></tbody></table></div><h2 id="locale-strings"><a href="#locale-strings" class="header-anchor">#</a> Locale Strings</h2><p>Use locale strings for UI text that is not tied to a database record: button labels, flash messages, form labels, navigation items, and validation messages. Translations are stored in <code>lang/en.json</code> files inside your plugin or theme directory and accessed with the <code>__()</code> helper in both PHP and Twig.</p><p>This approach works identically whether you have one site or many. Every plugin should use it for its interface strings.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token function">__</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Save Changes&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>Save Changes<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>Read the <a href="./localization.html">Localization article</a> for plugin lang files, or the <a href="./../../cms/multisite/localization.html">Theme Localization article</a> for theme lang files.</p><h2 id="multisite"><a href="#multisite" class="header-anchor">#</a> Multisite</h2><p>Use the Multisite trait when the <strong>entire record</strong> should exist independently per site. Each site gets its own copy of the record with its own content. This is the right choice when a blog post on the English site is completely different content from the French site, not a translation of the same post.</p><p>The trait uses <code>site_id</code> and <code>site_root_id</code> columns to track which record belongs to which site, and can propagate shared attributes (like a category code) across all copies.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Multisite</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$propagatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;category_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Read the <a href="./multisite.html">Multisite article</a> for the full trait API.</p><h2 id="translatable"><a href="#translatable" class="header-anchor">#</a> Translatable</h2><p>Use the Translatable trait when a record is the <strong>same entity</strong> but needs translated attributes. One record exists in the database; translations are stored in a side table. This is the right choice when a product is called &quot;Widget&quot; in English and &quot;Gadget&quot; in French, but it is the same product with the same SKU and price.</p><p>The trait intercepts <code>getAttribute</code> and <code>setAttribute</code> based on the active site locale, so existing code reads and writes translations without any changes.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Translatable</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$translatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;description&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Read the <a href="./translatable.html">Translatable article</a> for the full trait API.</p><h2 id="multisitegroup"><a href="#multisitegroup" class="header-anchor">#</a> MultisiteGroup</h2><p>Use the MultisiteGroup trait for <strong>multi-tenancy</strong> — when records should be scoped to a site group. A site group typically represents a distinct website (e.g., a &quot;Dogs&quot; website and a &quot;Cats&quot; website that share the same CMS installation but have separate product catalogs).</p><p>The trait applies a global scope that filters records by <code>site_group_id</code>, so each tenant only sees its own data.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>MultisiteGroup</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Read the <a href="./multisite-group.html">MultisiteGroup article</a> for the full trait API.</p><h2 id="combining-approaches"><a href="#combining-approaches" class="header-anchor">#</a> Combining Approaches</h2><p><strong>MultisiteGroup + Translatable</strong> is the natural combination for multi-tenant sites with translations. Each record is scoped to a site group and its attributes can be translated across the languages within that group.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>MultisiteGroup</span><span class="token punctuation">;</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Translatable</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$translatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;description&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><strong>Multisite + Translatable</strong> is generally not combined because the Multisite trait already creates one record per site — there is nothing left to translate at the attribute level.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./localization.html">Localization</a></li><li><a href="./multisite.html">Multisite Trait</a></li><li><a href="./translatable.html">Translatable Trait</a></li><li><a href="./multisite-group.html">MultisiteGroup Trait</a></li><li><a href="./../../cms/multisite/localization.html">Theme Localization</a></li><li><a href="./../../cms/multisite/tailor.html">Tailor Localization</a></li><li><a href="./../services/site.html">Site Service</a></li></ul></div>`,31))])}const w=o(r,[["render",u]]);export{f as __pageData,w as default};
